NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Petrus, Apostel Jesu Christi, an die Erwählten Fremden [die] in der Zerstreuung in Pontus, Galatien, Kappadozien, Asien und Bithynien [leben],',
        2: 'nach der Vorherbestimmung (Vorsehung) Gottes des Vaters in der Heiligung durch den Geist zum Gehorsam und zur Besprengung mit dem Blut Jesu Christi, Gnade sei mit euch, und Friede wachse (vermehre sich = in Fülle).',
        3: 'Gelobt sei der Gott und Vater unseres Herrn Jesus Christus, der uns wegen seiner großen Barmherzigkeit wieder gezeugt hat zu einer lebendigen Hoffnung durch die Auferstehung Jesu Christi von den Toten,',
        4: 'zu einem unvergänglichen, reinen und unverwelklichen (unvergänglichen) Heilsbesitz (Erbe), für euch im Himmel aufbewahrt,',
        5: 'die ihr durch Gottes Macht (Kraft) bewahrt seid durch den Glauben zur Rettung, die bereitet ist, um zur letzten Zeit (Endzeit) offenbart zu werden.',
        6: 'In ihr jubelt ihr, die ihr jetzt ein wenig, wenn es sein soll, betrübt werdet durch mannigfache Prüfungen (Erprobungen),',
        7: 'damit die Echtheit eures Glaubens, die viel wertvoller ist als das vergängliche Gold, das doch durch das Feuer geprüft wird, (gefunden =) erwiesen wird zu Lob und Ruhm und Ehre bei der Offenbarung Jesu Christi.',
        8: 'Ihn liebt ihr, obwohl ihr ihn nicht seht; an ihn glaubt ihr, ohne ihn jetzt zu sehen, doch jubelnd mit unaussprechlicher und verklärter Freude,',
        9: 'weil ihr das Ziel eures Glaubens erreicht, die Rettung eures Lebens.',
        13: 'Darum umgürtet die Lenden eurer Gesinnung, seid nüchtern und hofft ganz auf die Gnade, die euch in der Offenbarung Jesu Christi angeboten wird.',
        14: 'Als Kinder des Gehorsams gleicht euch nicht den Begierden von früher aus der Zeit der Unwissenheit an,',
        15: 'sondern wie der, der euch berufen hat, heilig ist, so seid auch ihr heilig in eurer ganzen Lebensweise!',
        16: 'Denn es steht geschrieben: Seid Heilige, weil ich heilig bin!',
        17: 'Und wenn ihr den als Vater anruft, der jeden ohne Ansehen der Person nach seinen Taten richtet, so führt euer Leben, während eures Aufenthalts in der Fremde, in Gottesfurcht.',
        18: 'Ihr wisst, dass ihr nicht mit Vergänglichem, mit Silber oder Gold, erlöst worden seid aus eurer nichtigen, von den Vorfahren übernommenen Lebensweise,',
        19: 'sondern mit dem kostbaren Blut Christi als eines unschuldigen und makellosen Lammes.',
        20: 'Er war schon vorher ausersehen worden – vor der Grundlegung der Welt, aber offenbar geworden ist er am Ende der Zeiten – um euretwillen.',
        21: 'Die ihr durch ihn zum Glauben gekommen seid an Gott, der ihn auferweckt hat von den Toten, der ihm Herrlichkeit gab, damit euer Glaube auch Hoffnung ist auf Gott.',
    },
    2: {
        1: 'Legt nun ab alle Schlechtigkeit und alle List und Heucheleien und Neid und allerlei Verleumdung (üble Nachrede).',
        2: 'Wie neugeborene Kinder verlangt nach geistiger, unverfälschter (reiner) Milch, damit ihr durch sie zunehmt (wachst) zum Heil (Rettung, Bewahrung, Erlösung),',
        3: 'wenn ihr „schmecktet, dass der Herr gütig ist“(Psalm 34,9).',
        4: 'Geht zu ihm, dem lebendigen Stein, von [den] Menschen zwar verworfen, bei Gott aber erwählt [und] wertvoll,',
        5: 'und selbst wie lebendige Steine (werdet erbaut =) lasst euch erbauen zu einem geistigen (geistlichen) Haus, zu einer heiligen Priesterschaft, um geistige (geistliche) Opfer darzubringen, die Gott willkommen sind durch Jesus Christus.',
        6: 'Deshalb steht in der Schrift: „Schau (siehe), ich lege in Zion einen Eckstein, [einen] erwählten, wertvollen, und wer an ihn glaubt, wird nicht zuschanden (beschämt) werden.“(Jesaja 28,16)',
        7: 'Für euch nun, die Gläubigen, [ist er ein] Wert, für [die, die] nicht glauben aber [ist er] „ein Stein, den die Bauleute verwarfen, dieser wurde zum Eckstein“(Psalm 118,22),',
        8: 'und „ein Stein des Anstoßes und ein Fels, über den man zu Fall kommt“(Jesaja 8,14). Sie stoßen sich [an ihm], weil sie dem Wort ungehorsam sind, wozu sie auch [von Gott] bestimmt wurden.',
        9: 'Ihr aber [seid] ein erwähltes Geschlecht (Volk), ein Königshaus, eine Priesterschaft, ein heiliges Volk (Stamm), ein Volk zum Eigentum (Besitz), damit ihr die guten Taten (Wunder) dessen weit hinaus verkündigt, der euch aus der Finsternis in sein wunderbares Licht gerufen hat.',
        10: 'Die ihr einst „kein Volk“(Nicht-Volk, Hosea 1,6.9) [wart], jetzt aber Volk Gottes [seid], die „kein Erbarmen fanden“(Nicht-Erbarmen, Hosea 2,25), jetzt aber Erbarmen finden.',
        18: '(Die =) Ihr Sklaven, gehorcht den Herren (in aller Furcht =) mit großem Respekt, nicht allein den guten und milden, sondern auch den (krummen, verdrehten =) schlechten.',
        19: 'Dies nämlich ist [die] Gnade, wenn jemand (durch Bewusstsein Gottes =) der sich Gottes bewusst ist, Kümmernisse erträgt - wenn er ungerechterweise leidet.',
        20: 'Denn welcher Ruhm [liegt darin], dass ihr ertragt, für Verfehlungen misshandelt zu werden? Dass ihr aber ertragt, für Rechtschaffenheit zu leiden, das ist Gnade von Gott.',
        21: 'Denn dazu nämlich seid ihr berufen. Denn auch Christus hat für euch gelitten und euch ein Vorbild hinterlassen, damit ihr seinen Fußtapfen nachfolgt.',
        22: "Der keine Sünde (tat =) beging, ''noch wurde List (Betrug) in seinem Mund gefunden''.",
        23: 'Der, obwohl er beschimpft (geschmäht) wurde, nicht zurückschimpfte (zurückschmähte), obwohl er litt, nicht drohte, sondern [es] dem übergab, der gerecht richtet.',
        24: "Der ''unsere Sünden selbst hinauftrug'' an (in) seinem Körper (Leib) auf das Holz, damit wir, weil wir den Sünden gestorben sind, durch die (für die) Gerechtigkeit leben. ''Durch seine Strieme seid ihr geheilt''.",
        25: "Denn ihr ''irrtet herum wie Schafe'', aber jetzt seid ihr zurückgekehrt (umgekehrt) zum Hirten und Beschützer (Aufseher) eures Lebens.",
    },
    3: {
        9: 'und vergeltet nicht Böses (Schlechtes) mit (für, anstelle von) Bösem oder Schmähung (Beschimpfung) mit Schmähung, im Gegenteil aber segnet, weil ihr dazu berufen wurdet, damit ihr Segen erbt!',
        18: 'Denn auch Christus hat ein für allemal (einmal) für die Sünden gelitten, ein Gerechter für Ungerechte, um euch Zugang bei Gott zu verschaffen. Er wurde zwar leiblich (im Leib) getötet, aber geistlich (im Geist) lebendig gemacht.',
        19: 'Wobei er auch zu den Geistern im Gefängnis ging und ihnen verkündigte,',
        20: 'die einst ungehorsam waren, als Gottes Langmut (Geduld) abwartete (wartete) in den Tagen Noahs, als die Arche gebaut wurde, in der wenige, das heißt acht Personen (Menschenleben), durch das Wasser hindurch gerettet wurden.',
        21: 'Es ist das Gegenbild der Taufe, die auch euch heute (jetzt) rettet, nicht durch die Entfernung des körperlichen Drecks (Schmutzes), sondern als Zusage einer (guten =) festen Bindung an Gott durch die Auferstehung Jesu Christi,',
        22: 'der zur Rechten Gottes ist, nachdem er in den Himmel gelangt ist und ihm Engel und Mächte und Gewalten unterworfen wurden.',
    },
    5: {
        1: 'Die Ältesten bei euch {nun} bitte (ermahne) ich, der Mitälteste und Zeuge der Leiden Christi, auch der Teilnehmer an der Herrlichkeit, die offenbart werden wird:',
        2: 'Leitet (weidet) die Herde Gottes bei euch, indem ihr für sie sorgt (sie beaufsichtigt) nicht gezwungen, sondern freiwillig gemäß Gottes [Auftrag, Gebot], auch nicht um Gewinns willen (aus Profitgier), sondern bereitwillig,',
        3: 'noch wie Herrscher über [euren] Anteil [an der Herde], sondern (Vorbilder gewordene =) als Vorbilder der Herde.',
        4: 'Und wenn der Erzhirte (Oberhirte) erscheinen wird (sich zeigen wird), werdet ihr den unverwelklichen (unvergänglichen) Kranz der Herrlichkeit (Ehre) erlangen.',
        5: 'Ebenso (in gleicher Weise) [ihr] Jungen, ordnet euch den Ältesten (Älteren) unter! Alle aber legt (zieht) den anderen gegenüber die Demut an, denn Gott „widersetzt sich den Stolzen, den Demütigen aber gibt er Gnade“.',
        6: 'Beugt euch {nun} unter die starke Hand Gottes, damit er euch zu gegebener Zeit erhöht,',
        7: 'indem ihr all eure Sorge auf ihn legt, denn er kümmert sich um euch.',
        8: 'Seid besonnen (nüchtern), seid wachsam (haltet die Augen offen). Euer Feind, der Widersacher (Verleumder, Teufel) geht umher „wie ein brüllender Löwe“(Psalm 22,14) und sucht, wen er verschlingen kann (jemanden zum Verschlingen);',
        9: 'dem widersteht fest im Glauben, weil ihr wisst, dass sich die selben Leiden an eurer Bruderschaft in der Welt vollziehen.',
        10: 'Aber der Gott aller Gnade, der euch berufen hat zu seiner ewigen Herrlichkeit in Christus Jesus, nachdem ihr ein wenig gelitten habt, wird [euch] zurechthelfen (in Ordnung bringen, vollenden), stark machen (befestigen), Kraft verleihen, fest gründen (befestigen).',
        11: 'Ihm sei die Macht (Kraft, Stärke) in Ewigkeit. Amen.',
        12: 'Durch Silvanus, den treuen Bruder, wie ich meine, habe ich euch kurz geschrieben, um zu ermahnen und zu bezeugen, dass dies die wahre (rechte, wirkliche, echte) Gnade Gottes ist, in der ihr steht',
        13: 'Es grüßt euch in Babylon die mit Auserwählte und Markus, mein Sohn.',
        14: 'Grüßt einander mit dem Kuss der Liebe. Friede sei mit euch allen, die [ihr] in Christus [seid]!',
    },
}
